-- KB-024 object-level authorization semantic correction. Additive; no assessment or deployment decision changes.
UPDATE risk_knowledge_entries SET problem_json='{"statement":"A user can read or modify another assessment, project, runtime event, approval or report by changing an identifier.","customer_symptom":"A user or operator may observe a user can read or modify another assessment, project, runtime event, approval or report by changing an identifier; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"An authenticated actor or service identity can access another principal or tenant''s object through direct or indirect identifiers, alternate routes or missing server-side object authorization.","affected_assets":["tenant and workspace-scoped objects","object identifiers and ownership relationships","assessment evidence, approvals and reports","service identities and authorization audit events"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-user platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"Between the authenticated principal and server-enforced tenant, ownership and operation-level authorization for each object access.","operational_impact":"If a user can read or modify another assessment, project, runtime event, approval or report by changing an identifier, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-024 object ownership, tenancy, authorization policy or query change","ARL-KB-024 new direct, indirect, export or service-method object route","ARL-KB-024 cross-tenant or cross-user access or fail-open incident","ARL-KB-024 assessed build, scope or evidence expiry change"],"review_status":"candidate semantic correction; customer and independent practitioner validation required"}', content_digest='b87d66e149019f46359d6cc3c4c81b0c34d003e11573b8876e16d1fa178996d5', updated_at='2026-10-10' WHERE id='ARL-KB-024';
UPDATE risk_knowledge_checks SET objective='Determine whether server-side object authorization denies access outside the authenticated actor, tenant, ownership and allowed operation for each read, update, export and delete path.', method='Inspect the owner-approved role/object-operation matrix and server-side query guards. With separate written owner authorization, use synthetic staging identities and objects to exercise bounded positive operations and denied cross-user, cross-tenant, swapped-ID, alternate-route, service-identity and missing-policy variants. Correlate decisions, response payloads, object state and audit trails.', required_evidence_json='["ARL-KB-024 exact assessed system, build version, environment, tenant, workspace, synthetic identities, object types and protected operation scope","ARL-KB-024 organisation-approved actor, role, tenant, ownership and object-operation authorization matrix with accountable policy owner","ARL-KB-024 server-side source or configuration evidence for object-scoped queries, alternate routes, service identities and fail-closed authorization checks","ARL-KB-024 bounded positive evidence of approved synthetic same-tenant object reads, changes, exports and deletes, with observed outputs and object state","ARL-KB-024 bounded negative evidence of cross-user, cross-tenant, identifier-swap, alternate-route and missing-policy requests denied before any data exposure or side effect","ARL-KB-024 observed runtime authorization decisions, response payload checks, before-and-after object state and downstream audit events proving allow and deny outcomes","ARL-KB-024 tester and reviewer identity, roles, timestamps, exact version, evidence digest, exceptions and accountable human decision"]', pass_condition='KB-024 passes only after accountable human review establishes exact-version authorization policy and server enforcement, successful authorized object operations, denied cross-user and cross-tenant direct or alternate access before any payload leakage or side effect, and corroborating runtime/audit evidence with documented limitations.', fail_condition='KB-024 fails or requires review if unauthorized object access, information disclosure, export or mutation occurs; if authorization is UI-only, based on caller-supplied ownership, or fails open through alternate paths; or if exact-version negative tests, runtime observations or human review are missing.', content_digest='0a2a2b75c7f0643a5305fe71b855cbf74e4fd31811923af76dcddeac009fc06d', updated_at='2026-10-10' WHERE entry_id='ARL-KB-024';
UPDATE risk_knowledge_solutions SET retest_acceptance_json='["ARL-KB-024: Exact revised object-authorization policy, ownership matrix, deployed version and relevant digests are recorded.","ARL-KB-024: Synthetic in-scope object operations succeed with expected outputs and recorded before-and-after state.","ARL-KB-024: Cross-user, cross-tenant, identifier-swap, alternate-route and missing-policy attempts fail closed with no unauthorized payload or side effect and correlated audit records.","ARL-KB-024: An accountable human reviewer records test limitations, exceptions, residual risk and the exact-version retest decision."]', content_digest='baa311c7070f0a8465e422153ca0d003fbbf4753e463803eb7193ef1a9708b59', updated_at='2026-10-10' WHERE entry_id='ARL-KB-024';
